-- ============================================================================
-- Import CSV Expense Data into Website Database
-- ============================================================================
-- Run this in phpMyAdmin → SQL tab
-- Database: personal_expense_tracker
-- ============================================================================

USE personal_expense_tracker;

-- ============================================================================
-- STEP 1: Find your user ID
-- ============================================================================
-- Run this first to see your user ID:
SELECT id, username, email FROM users;
-- Note your ID (probably 1). Replace @uid below with your actual user ID.

SET @uid = 1;  -- ⚠️ CHANGE THIS to your actual user ID from the query above

-- ============================================================================
-- STEP 2: Create the 8 categories for your user (if they don't exist)
-- ============================================================================

-- ============================================================================
-- STEP 3: Insert expenses from Dataset 1 (300 rows)
-- Maps category names → category_id using a subquery
-- ============================================================================

-- ============================================================================
-- STEP 4: Verify the data was inserted
-- ============================================================================
SELECT 
    c.name AS category,
    COUNT(*) AS total_expenses,
    SUM(e.amount) AS total_amount
FROM expenses e
JOIN categories c ON e.category_id = c.id
WHERE e.user_id = @uid
GROUP BY c.name
ORDER BY total_expenses DESC;
